import { XP_REWARDS } from '@/config/constants';
import { toggleId } from '@/core/rewards';
import { SEED_FORUM_POSTS } from '@/data/forum';
import type { ForumComment, ForumPost } from '@/types';
import type { SliceCreator } from '@/store/types';

/** Fields the author fills in; the rest is generated by createForumPost. */
export type NewForumPost = Omit<
  ForumPost,
  | 'id'
  | 'authorId'
  | 'authorName'
  | 'authorAvatar'
  | 'authorAvatarBg'
  | 'createdAt'
  | 'upvotes'
  | 'commentsCount'
  | 'comments'
>;

export interface ForumSlice {
  forumPosts: ForumPost[];
  createForumPost: (post: NewForumPost) => void;
  upvoteForumPost: (postId: string) => void;
  addCommentToPost: (postId: string, content: string) => void;
  markAnswerAccepted: (postId: string, commentId: string) => void;
}

export const createForumSlice: SliceCreator<ForumSlice> = (set, get) => ({
  forumPosts: SEED_FORUM_POSTS,

  createForumPost: (data) => {
    const { user } = get();
    const post: ForumPost = {
      ...data,
      id: `post-${Date.now()}`,
      authorId: user.id,
      authorName: user.displayName,
      authorAvatar: user.avatarSeed,
      authorAvatarBg: user.avatarBg,
      createdAt: 'Just now',
      upvotes: 1,
      commentsCount: 0,
      comments: [],
    };
    set((s) => ({ forumPosts: [post, ...s.forumPosts] }));
    get().addXp(XP_REWARDS.forumPost, false);

    if (data.category === 'projects' || data.isCollaborative) get().grantBadge('project-architect');
  },

  upvoteForumPost: (postId) =>
    set((s) => {
      const already = (s.user.upvotedPostIds ?? []).includes(postId);
      return {
        user: { ...s.user, upvotedPostIds: toggleId(s.user.upvotedPostIds, postId) },
        forumPosts: s.forumPosts.map((p) =>
          p.id === postId ? { ...p, upvotes: Math.max(0, p.upvotes + (already ? -1 : 1)) } : p,
        ),
      };
    }),

  addCommentToPost: (postId, content) => {
    const text = content.trim();
    if (!text) return;
    const { user } = get();
    const comment: ForumComment = {
      id: `comm-${Date.now()}`,
      authorId: user.id,
      authorName: user.displayName,
      authorAvatar: user.avatarSeed,
      authorAvatarBg: user.avatarBg,
      content: text,
      createdAt: 'Just now',
      upvotes: 0,
    };
    set((s) => ({
      forumPosts: s.forumPosts.map((p) =>
        p.id === postId
          ? { ...p, commentsCount: p.commentsCount + 1, comments: [...p.comments, comment] }
          : p,
      ),
    }));
    get().addXp(XP_REWARDS.forumComment, false);
  },

  markAnswerAccepted: (postId, commentId) =>
    set((s) => ({
      forumPosts: s.forumPosts.map((p) =>
        p.id === postId
          ? {
              ...p,
              isResolved: true,
              hasAcceptedAnswer: true,
              comments: p.comments.map((c) => ({ ...c, isAcceptedAnswer: c.id === commentId })),
            }
          : p,
      ),
    })),
});
